async function requestDetail(id){
 const r=await api(`/api/v1/events/${id}`);const fields=[["Service",`${r.port_name} · v${r.port_version}`],["Actual model",r.usage_source==="not_invoked"?"Not invoked":r.model||"Unknown"],["Connection",r.usage_source==="not_invoked"?"No upstream call":r.connection_name||"Unknown"],["Started",date(r.started)],["End-to-end latency",ms(r.latency_ms)],["First content token",ms(r.ttft_ms)],["Input tokens",r.input_tokens??"Unknown"],["Output tokens",r.output_tokens??"Unknown"],["Estimated cost",r.cost_micros==null?"Not priced":money(r.cost_micros)],["Usage source",r.usage_source],["Project",state.projects.find(p=>p.id===r.project_id)?.name||"User playground"],["Transport",r.stream?"Streaming":"JSON response"]];
 PliqraLayout.rememberDrawerFocus();document.getElementById("app").inert=true;
 document.getElementById("drawer-root").innerHTML=`<div class="overlay" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="request-title" tabindex="-1"><div class="modal-head"><div><h2 id="request-title">Request details</h2><p class="mono">${esc(r.id)}</p></div>${ibtn("Close request details","close-drawer","close")}</div><div class="modal-content"><div style="margin-bottom:23px">${badge(r.status)}</div><div class="detail-grid">${fields.map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join("")}</div>${r.error?`<div class="notice warning">${icon("info")}${esc(r.error)}</div>`:""}<h3>Why this model?</h3><p style="font-size:11px;margin-top:8px;color:var(--text-secondary)">Eligibility checks and upstream attempts, in execution order.</p><div class="timeline">${r.decisions.map(d=>`<div class="timeline-row"><span class="timeline-icon ${d.eligible===false?"excluded":""}">${icon(d.eligible===false?"close":d.outcome?"refresh":"check")}</span><div><strong>${esc(d.model||d.deployment_id||"Routing")}${d.selected?' <span class="pill">Selected</span>':""}</strong><p>${esc(d.reason||d.outcome)}</p>${d.connection?`<small>${esc(d.connection)}</small>`:""}</div></div>`).join("")}</div><div class="notice">${icon("shield")} Content capture is disabled by default and can be enabled per service. Usage is provider-reported when available; cost is estimated from configured prices.</div></div></aside>`;
 if(window.PliqraUI)document.querySelector(".drawer .modal-content").insertAdjacentHTML("beforeend",PliqraUI.requestExtras(r));
 if(window.PliqraFabric)document.querySelector(".drawer .modal-content").insertAdjacentHTML("beforeend",PliqraFabric.requestDetails(r));
 document.querySelector(".drawer").focus();
}

async function auditModal(offset=0){const rows=await api(`/api/v1/audit?offset=${offset}`);modal("Audit trail","Configuration changes and authentication events. Provider secrets are excluded.",rows.length?`<div class="timeline">${rows.map(r=>`<div class="timeline-row"><span class="timeline-icon">${icon("history")}</span><div><strong>${esc(r.action)}</strong><p>${esc(r.target)}</p><small>${date(r.created)} · ${esc(state.users.find(u=>u.id===r.actor)?.name||r.actor)}</small></div></div>`).join("")}</div>`:empty("history","No audit events","Changes will appear here."),null,null,btn("Previous","audit-page",null,"",`data-offset="${Math.max(0,offset-200)}" ${offset===0?"disabled":""}`)+btn("Older events","audit-page",null,"",`data-offset="${offset+200}" ${rows.length<200?"disabled":""}`));}

function searchModal(){modal("Search your workspace","Find a connection, model, or AI service.",`${field("Search","search","Type a model or service name…")}<div id="search-results" class="search-results"></div>`,null,null);const input=document.getElementById("f-search");input.addEventListener("input",()=>{const q=input.value.toLowerCase();const results=[...state.ports.map(p=>({label:p.name,type:"AI service",view:"services"})),...state.conns.map(c=>({label:c.name,type:"Connection",view:"connections"})),...state.conns.flatMap(c=>c.models.map(m=>({label:m.model,type:c.name,view:"connections"})))].filter(r=>q&&r.label.toLowerCase().includes(q)).slice(0,12);document.getElementById("search-results").innerHTML=results.map(r=>`<button type="button" class="search-result" data-action="search-nav" data-view="${r.view}" data-query="${esc(r.label)}"><span>${esc(r.label)}</span><small>${esc(r.type)}</small></button>`).join("")||`<p class="muted" style="font-size:11px">${q?"No matching models or services.":"Start typing to search your connected models."}</p>`;});}

async function copy(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return;}const el=document.createElement("textarea");el.value=text;el.style.position="fixed";el.style.opacity="0";document.body.append(el);el.select();const success=document.execCommand("copy");el.remove();if(!success)throw new Error("Clipboard unavailable. Select and copy the text manually.");}
function download(name,text,type="application/json"){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function sendChat(){
 if(state.chatBusy)return;const input=document.getElementById("chat-input");const content=input.value.trim();if(!content)return;
 const service=document.getElementById("f-play-service").value;const maxTokens=Number(document.getElementById("f-play-tokens").value);const temperature=Number(document.getElementById("f-play-temp").value);
 if(!maxTokens||maxTokens<1||maxTokens>32768||temperature<0||temperature>2){toast("Check the output token limit and temperature.",true);return;}
 const attribution=window.PliqraUI?PliqraUI.playContext():{};state.playPort=service;state.chat.push({role:"user",content});const messages=state.chat.map(({role,content})=>({role,content}));state.chat.push({role:"assistant",content:""});state.chatBusy=true;controller=new AbortController();renderView();
 try{
  const response=await fetch(BASE+(window.PliqraFabric?PliqraFabric.playPath():"/v1/chat/completions"),{method:"POST",headers:{"Content-Type":"application/json","X-Pliqra-CSRF":state.session.csrf},credentials:"same-origin",body:JSON.stringify({model:service,messages,stream:true,max_tokens:maxTokens,temperature,pliqra:attribution}),signal:controller.signal});
  if(!response.ok){const failure=await response.json();state.lastRequest=failure.detail?.request_id||null;throw new Error(errorMessage(failure));}state.lastRequest=response.headers.get("X-Request-ID");
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer="";let doneMarker=false;
  while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split("\n");buffer=lines.pop();for(const line of lines){if(!line.startsWith("data:"))continue;const data=line.slice(5).trim();if(data==="[DONE]"){doneMarker=true;continue;}if(!data)continue;const chunk=JSON.parse(data);if(chunk.error)throw new Error(chunk.error.message);const delta=chunk.choices?.[0]?.delta;state.chat.at(-1).content+=delta?.content||"";if(delta?.tool_calls)state.chat.at(-1).content+="\n[Tool call received. Use the API to complete the tool loop.]";const target=document.getElementById("chat-messages");if(target){target.innerHTML=chatMessages();target.scrollTop=target.scrollHeight;}}if(done)break;}
  if(!doneMarker)throw new Error("The stream ended before the completion marker.");
 }catch(error){if(error.name==="AbortError"){toast("Response stopped. Usage may be incomplete.");}else{toast(error.message,true);if(!state.chat.at(-1).content)state.chat.at(-1).content="Request failed: "+error.message;}}
 finally{state.chatBusy=false;controller=null;await refreshData().catch(()=>{});if(state.view==="playground"){renderView();document.getElementById("chat-messages").scrollTop=999999;}}
}

function renderAuth(){
 const setup=state.session.setup_required;
 const art=`<svg viewBox="0 0 400 125" aria-hidden="true"><path d="M60 30h75q25 0 25 30v5h65m-165 40h75q25 0 25-30V65m65 0h65q25 0 25-25V30h30m-120 35h65q25 0 25 25v15h30" stroke="var(--auth-diagram-line)" stroke-width="1.5" fill="none"/><rect x="10" y="10" width="60" height="42" rx="11" fill="var(--auth-diagram-surface)" stroke="var(--auth-diagram-border)"/><text x="40" y="36" fill="var(--auth-diagram-text)" text-anchor="middle" font-family="monospace" font-size="13">API</text><rect x="10" y="84" width="60" height="40" rx="11" fill="var(--auth-diagram-surface)" stroke="var(--auth-diagram-border)"/><text x="40" y="109" fill="var(--auth-diagram-text)" text-anchor="middle" font-family="monospace" font-size="12">LLM</text><rect x="203" y="39" width="54" height="53" rx="13" fill="var(--auth-diagram-accent)"/><path d="M224 48v11m12-11v11m-18 0h24v5a12 12 0 0 1-24 0v-5Zm12 17v8" stroke="var(--auth-diagram-ink)" fill="none" stroke-width="2.2" stroke-linecap="round"/><circle cx="360" cy="30" r="18" fill="var(--auth-diagram-surface)" stroke="var(--auth-diagram-border)"/><path d="m353 30 5 5 8-10" stroke="var(--auth-diagram-text)" fill="none" stroke-width="1.8"/><circle cx="360" cy="105" r="18" fill="var(--auth-diagram-surface)" stroke="var(--auth-diagram-border)"/><path d="M351 109v-5m9 5V98m9 11V94" stroke="var(--auth-diagram-text)" fill="none" stroke-width="1.8"/></svg>`;
 document.getElementById("app").innerHTML=`<div class="auth"><div class="auth-art"><div class="brand"><span class="brand-mark"><img src="${BASE}/static/favicon.svg" width="31" height="31" alt=""></span>Pliqra</div><div class="auth-art-center"><div class="eyebrow">Every model. One connection.</div><h1>Know your model.<br> <em>Know the agreement.</em></h1><p>Connect an endpoint, verify what works, and see when your service contract changes.</p><div class="auth-diagram">${art}</div></div><div class="auth-art-footer">Self-hosted. Platform independent. Built around an open contract.</div></div><div class="auth-form-wrap"><form class="auth-form" id="auth-form"><span class="pill" style="margin-bottom:20px">${setup?"Your workspace starts here":"Your models are waiting"}</span><h2>${setup?"Make yourself at home.":"Welcome back."}</h2><p class="muted">${setup?"Create your administrator account. Then bring your first model endpoint.":"Sign in to your Pliqra workspace."}</p>${setup?field("Your name","name","e.g. Alex Morgan","text","",'required autocomplete="name"'):""}${field("Email address","email","you@company.com","email","",'required autocomplete="username"')}${field("Password","password",setup?"At least 12 characters":"Your password","password","",`required ${setup?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'}`)}<div id="auth-error" role="alert">${new URLSearchParams(location.search).has("auth_error")?'<div class="form-error">Company sign-in could not be completed. Check the provider configuration.</div>':""}</div><button type="submit" class="btn primary" id="auth-submit">${setup?"Create workspace":"Sign in"}${icon("arrow")}</button>${!setup&&state.session.identity_providers?.length?`<div class="auth-divider">or use company sign-in</div>${state.session.identity_providers.map(p=>`<a href="${BASE}/auth/${esc(p.protocol||"oidc")}/${esc(p.id)}/login" class="btn" style="display:flex;margin-top:8px;width:100%">${icon("shield")}${esc(p.name)}</a>`).join("")}`:""}<p class="auth-foot">Your data is stored on this instance.<br>No external account or cloud service required.</p></form></div></div>`;
 document.getElementById("auth-form").addEventListener("submit",async e=>{e.preventDefault();const b=document.getElementById("auth-submit");b.disabled=true;try{const data=await api(setup?"/api/v1/setup":"/api/v1/login",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.session={...state.session,...data,setup_required:false};const requested=location.hash.slice(1);if([...navigation,...management].some(x=>x[0]===requested))state.view=requested;await refreshData();renderShell();}catch(error){document.getElementById("auth-error").innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}finally{if(b.isConnected)b.disabled=false;}});
}

document.addEventListener("click",async e=>{
 const el=e.target.closest("[data-action]");if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==="skip-content"){e.preventDefault();document.getElementById("view").focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"});return;}
 try{
  if(a==="j-copy-key"){await copy(el.dataset.key);toast("Access key copied.");return;}
  if(window.PliqraJourney&&await PliqraJourney.handle(a))return;
  if(window.PliqraFleet&&await PliqraFleet.handle(a,id,el,e))return;
  if(window.PliqraEnterprise&&await PliqraEnterprise.handle(a,id,el,e))return;
  if(window.PliqraUI&&await PliqraUI.handle(a,id,el,e))return;
  if(a==="nav")await navigate(el.dataset.view);
  else if(a==="menu")PliqraLayout.menu(!document.getElementById("sidebar").classList.contains("open"));
  else if(a==="close-menu")PliqraLayout.menu(false);
  else if(a==="connect")connectModal();
  else if(a==="close-modal")closeModal();
  else if(a==="close-drawer")PliqraLayout.closeDrawer();
  else if(a==="logout"&&state.session.federated_logout){const result=await api(state.session.federated_logout,{method:"POST",body:"{}"});location.href=result.redirect_url;}
  else if(a==="logout"){await api("/api/v1/logout",{method:"POST",body:"{}"});location.hash="overview";location.reload();}
  else if(a==="check-connection"){el.disabled=true;await api(`/api/v1/connections/${id}/check`,{method:"POST",body:"{}"});await refreshData();renderView();toast("Connection checked and model list refreshed.");}
  else if(a==="disconnect")modal("Disconnect this endpoint?","Existing request history will be preserved.","<p>All deployments on this connection will be disabled. Services using them may become unavailable.</p>","Disconnect endpoint",async()=>{await api(`/api/v1/connections/${id}`,{method:"DELETE",body:"{}"});await changed("Endpoint disconnected.");});
  else if(a==="deployment")deploymentModal(id);
  else if(a==="service")serviceModal(id);
  else if(a==="deployment-up"||a==="deployment-down"){e.preventDefault();const row=el.closest(".check-row");if(a==="deployment-up"&&row.previousElementSibling)row.parentElement.insertBefore(row,row.previousElementSibling);else if(a==="deployment-down"&&row.nextElementSibling)row.parentElement.insertBefore(row.nextElementSibling,row);}
  else if(a==="manifest")await manifestModal(id);
  else if(a==="open-play"){if(id)state.playPort=state.ports.find(p=>p.id===id)?.name||state.playPort;state.chat=[];state.lastRequest=null;await navigate("playground");}
  else if(a==="project")projectModal(id);
  else if(a==="key")keyModal();
  else if(a==="revoke-key")modal("Revoke this access key?","Applications using it will lose access immediately.","<p>This key cannot be recovered. Create a new key if the application needs access again.</p>","Revoke key",async()=>{await api(`/api/v1/keys/${id}`,{method:"DELETE",body:"{}"});await changed("Access key revoked.");});
  else if(a==="identity")identityModal();
  else if(a==="disable-idp")modal("Disable this identity provider?","Existing sessions for this provider will be revoked.","<p>Local administrator accounts remain available. Users cannot sign in through this provider while it is disabled.</p>","Disable provider",async()=>{await api(`/api/v1/identity-providers/${id}`,{method:"DELETE",body:"{}"});await changed("Identity provider disabled.");});
  else if(a==="user")userModal();
  else if(a==="edit-user")editUser(id);
  else if(a==="request-detail"){closeModal();await requestDetail(id);}
  else if(a==="audit")await auditModal();
  else if(a==="audit-page")await auditModal(Number(el.dataset.offset));
  else if(a==="search")searchModal();
  else if(a==="search-nav"){closeModal();await navigate(el.dataset.view);state.query=el.dataset.query;renderView();}
  else if(a==="export"){const response=await fetch(BASE+`/api/v1/usage.csv?${reportQuery()}`);if(!response.ok)throw new Error("Export failed");download("pliqra-usage.csv",await response.text(),"text/csv");toast("Usage export downloaded.");}
  else if(a==="copy-example"){await copy(apiExample());toast("API example copied.");}
  else if(a==="load-api"){const schema=await api("/openapi.json");document.getElementById("api-routes").innerHTML=`<div class="api-routes">${Object.entries(schema.paths).flatMap(([path,methods])=>Object.entries(methods).map(([method,op])=>`<div class="api-route"><span class="api-method ${method}">${esc(method.toUpperCase())}</span><code>${esc(path)}</code><small>${esc(op.tags?.[0]||"")}</small></div>`)).join("")}</div>`;}
  else if(a==="download-manifest"){const manifest=await api(`/api/v1/ports/${id}/export`);download("pliqra-service.json",JSON.stringify(manifest,null,2));}
  else if(a==="send-chat")await sendChat();
  else if(a==="stop-chat")controller?.abort();
  else if(a==="clear-chat"){state.chat=[];state.lastRequest=null;renderView();}
  else if(a==="play-manifest")await manifestModal(state.ports.find(p=>p.name===state.playPort)?.id);
 }catch(error){toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}
});

document.addEventListener("change",async e=>{
 try{
  if(e.target.id==="period"){state.days=Number(e.target.value);delete state.reportFilters.start;delete state.reportFilters.end;state.eventOffset=0;await refreshData();renderView();}
  else if(e.target.id==="status-filter"){state.status=e.target.value;state.eventOffset=0;await refreshData();renderView();}
  else if(e.target.id==="f-play-service"){state.playPort=e.target.value;state.playProject="";state.playTeam="";state.chat=[];state.lastRequest=null;document.getElementById("chat-messages").innerHTML=chatMessages();document.getElementById("chat-last").innerHTML="";renderView();}
 }catch(error){toast(error.message,true);}
});
document.addEventListener("input",e=>{if(e.target.id!=="filter")return;state.query=e.target.value;state.eventOffset=0;clearTimeout(queryTimer);queryTimer=setTimeout(async()=>{try{if(state.view==="requests")await refreshData();renderView();}catch(error){toast(error.message,true);}},220);});
document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key==="k"&&state.session?.user){e.preventDefault();searchModal();}if(e.key==="Escape"){if(document.querySelector(".drawer")&&!document.getElementById("modal").open)PliqraLayout.closeDrawer();PliqraLayout.menu(false);}if(e.target.id==="chat-input"&&e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendChat();}if(e.key==="Enter"&&e.target.matches("tr[data-action]"))e.target.click();});
document.addEventListener("click",async e=>{const a=e.target.closest('[data-action="prev-page"],[data-action="next-page"]');if(!a||a.disabled)return;state.eventOffset=Math.max(0,state.eventOffset+(a.dataset.action==="next-page"?50:-50));await refreshData();renderView();});
window.addEventListener("hashchange",()=>{const view=location.hash.slice(1);if(view&&view!==state.view&&[...navigation,...management].some(x=>x[0]===view))navigate(view).catch(e=>toast(e.message,true));});

async function init(){try{state.session=await api("/api/v1/session");if(!state.session.user){renderAuth();return;}const view=location.hash.slice(1);if([...navigation,...management].some(x=>x[0]===view))state.view=view;await refreshData();renderShell();}catch(error){document.getElementById("app").innerHTML=`<div class="error-page"><h2>Could not open this workspace</h2><p>${esc(error.message)}</p><button class="btn" data-action="reload">Try again</button></div>`;document.querySelector('[data-action="reload"]').onclick=()=>location.reload();}}
init();
function dataSignature(){return JSON.stringify([state.conns,state.ports,state.usage?.summary,state.events.items.map(r=>[r.id,r.status,r.finished]),state.evaluations,state.operations,state.journey,state.gateways,state.guardrails,state.guardDecisions]);}
refreshTimer=setInterval(async()=>{if(!state.session?.user||state.chatBusy||document.getElementById("modal").open||document.querySelector(".drawer")||["INPUT","SELECT","TEXTAREA"].includes(document.activeElement?.tagName))return;try{const before=dataSignature();await refreshData();if(before!==dataSignature()&&["overview","requests","usage","connections","operations","evaluations","gateways","guardrails"].includes(state.view))renderView();}catch(_){}},15000);
